pdf.body:
    
    


        BILL TO
         
        PROJECT
      


        ${record.billaddress!''}
         
        ${record.custpage_apg_proj_name!''}
${record.custpage_apg_proj_address!''}
      
    

    
    


        INVOICE #
        INVOICE DATE
        PAYMENT TERMS
        CUSTOMER REFERENCE / PO
        CUSTOMER
      


        ${record.tranid}
        ${record.trandate}
        ${record.terms}
        ${record.otherrefnum}
        ${record.entity.entityid!''}
      
    

    
    


        
          FOR WORK COMPLETED THROUGH:  ${record.enddate!''}
        
      
    

    
    <#assign accContractAmt   = 0 />
    <#assign accWorkComplete  = 0 />
    <#assign accPrevInvoiced  = 0 />
    <#assign accCurrentBill   = 0 />
    <#assign accLessRetention = 0 />

    
      


          
          
            APG PROJECT  ${record.custpage_apg_proj_number!''}  CONTRACT ITEMS
          
          CONTRACT
AMOUNT
          %
COMPLETE
          TOTAL
TO DATE
          CURRENT
BILLING
        
      

      
        <#if record.item?has_content>
        <#list record.item as item>

          
          <#assign _origVal  = ((item.custpage_apg_orig_value!'')?has_content)?then((item.custpage_apg_orig_value)?number, 0) />
          <#assign _prevInv  = ((item.custpage_apg_prev_invoiced!'')?has_content)?then((item.custpage_apg_prev_invoiced)?number, 0) />
          <#assign _workComp = ((item.custpage_apg_amt_work_complete!'')?has_content)?then((item.custpage_apg_amt_work_complete)?number, 0) />
          <#assign _grossDue = ((item.custpage_apg_gross_due!'')?has_content)?then((item.custpage_apg_gross_due)?number, 0) />
          <#assign _totRet   = ((item.custpage_apg_total_retention!'')?has_content)?then((item.custpage_apg_total_retention)?number, 0) />
          <#assign _pct      = ((item.custpage_apg_pct_work_completed!'')?has_content)?then((item.custpage_apg_pct_work_completed)?number, 0) />

          
          <#assign accContractAmt   = accContractAmt   + _origVal  />
          <#assign accWorkComplete  = accWorkComplete  + _workComp />
          <#assign accPrevInvoiced  = accPrevInvoiced  + _prevInv  />
          <#assign accCurrentBill   = accCurrentBill   + _grossDue />
          <#assign accLessRetention = accLessRetention + _totRet   />



            
            
              ${record.custpage_apg_proj_number!''}
              <#if (item.custpage_apg_dept!'')?has_content> - ${item.custpage_apg_dept}</#if> -
            

            
            ${item.item!''}

            
            ${_origVal?string("#,##0.00")}

            
            ${_pct?string("#,##0.00")}%

            
            ${_prevInv?string("#,##0.00")}

            
            ${_grossDue?string("#,##0.00")}
          

        </#list>
        


           
          ${accContractAmt?string("#,##0.00")}
          
            <#if accContractAmt != 0>
              ${(accWorkComplete / accContractAmt * 100)?string("#,##0.00")}%
            <#else>
              0.00%
            </#if>
          
          ${accPrevInvoiced?string("#,##0.00")}
          ${accCurrentBill?string("#,##0.00")}
        
        </#if>
      
    

    
    


        
         

        
        
          


              Total To Date
              
                ${accWorkComplete?string("#,##0.00")}
              
            


              Sales Tax
              ${(record.taxtotal!'0')?replace('$','')?replace(',','')?number?string("#,##0.00")}
            


              Less Retainage
              ${accLessRetention?string("#,##0.00")}
            


              Less Previous Billed
              ${accPrevInvoiced?string("#,##0.00")}
            


              Total Tax This Invoice
              ${(record.taxtotal!'0')?replace('$','')?replace(',','')?number?string("#,##0.00")}
            


              Total Due This Invoice
              ${record.total}
